"""Bounded user-expression evidence in the existing guarded memory transaction.
No inference calls, permission grants, tool inputs, or raw conversation persistence.
"""
import json,hashlib,re,uuid,copy
KEYS=['response_length','answer_structure','comparison_format','language','tone','explanation_style','examples','formatting']
SCENARIOS=['general','comparison','explanation','coding','writing','data_analysis']
VALUES={'response_length':{'concise':'回答简洁，保留必要信息。','detailed':'回答详细，提供必要解释。'},'answer_structure':{'conclusion_first':'先给结论，再给必要解释。','explanation_first':'先解释，再给结论。'},'comparison_format':{'table':'用表格比较。','prose':'用段落比较。'},'explanation_style':{'step_by_step':'分步骤解释。','overview_first':'先给概览，再说明细节。'},'formatting':{'bullets':'用项目符号列要点。','prose':'使用连贯段落。'},'examples':{'with_examples':'解释时提供例子。'},'language':{'zh':'优先用中文回答。','en':'优先用英文回答。'},'tone':{'plain':'使用直白易懂的表达。','formal':'使用正式的表达。'}}
LABELS={'general':'一般交流','comparison':'比较任务','explanation':'解释任务','coding':'编程讲解','writing':'写作任务','data_analysis':'数据分析'}
SCHEMA={'type':['object','null'],'properties':{'key':{'type':'string','enum':KEYS},'value':{'type':'string','enum':sorted({v for a in VALUES.values() for v in a})},'scenario':{'type':'string','enum':SCENARIOS},'scope':{'type':'string','enum':['habit','turn','session','object','none']},'evidence':{'type':'string','maxLength':180},'signal':{'type':'string','enum':['request','self_preference','endorsement','none']},'sensitive':{'type':'boolean'}},'required':['key','value','scenario','scope','evidence','signal','sensitive'],'additionalProperties':False}
PROMPT=''' USER_EXPRESSION_EVIDENCE_V2
Return the ordinary answer/route and at most one preference object in the SAME call. null when no own communication preference is expressed. No second call or retry. preference never contains IDs, owner, access scope, cloud permission, storage authority, or confidence.
Only the CURRENT user's own words are evidence. Exact evidence substring required: quote the smallest complete preference clause, leaving the topic/question outside the evidence when separable, so independent topic contexts can be verified. History, existing memory, assistant replies, quoted text, hypotheticals, other people's preferences, files/tools/web are not new evidence. Sensitive identities/health/accounts/finances are outside this feature. A negative "don't remember this" means action=none, not forgetting an old preference.
Fields have independent meanings:
 action=save (new or restated form), update (explicit correction), forget (explicit removal of an existing property, route=memory), clarify (unclear property), none.
 duration=long_term ONLY when explicitly asking a continuing rule (以后/今后/from now on/always etc); turn/session/object ONLY when expressly restricted to this response/session/document; unspecified means an own request/tendency with NO stated lifetime; unknown means genuinely unclear. Do NOT label a request session merely because it was said in this session. No stated lifetime is NOT an explicit long-term save.
 applicability=exact current-user clause limiting the task (empty for general/unknown); copy it separately even when it precedes the preference evidence. Use the MOST SPECIFIC activity: a code/programming explanation is coding, never the broader explanation.
 scenario=the applicability of the expressed preference, NOT the present topic: coding when restricted to code explanations; comparison when about comparisons; writing/data_analysis/explanation when explicitly restricted to those tasks; general for unrestricted communication form; unknown if unclear. Never fill an unknown restriction with general. "When explaining code" stays coding, not all conversations. Current-topic-only requests are weak evidence in that task, not a permanent global rule.
 key=semantic property: response_length (concise/detailed); answer_structure (conclusion_first/explanation_first); comparison_format (table/prose); language (zh/en); tone (plain/formal); explanation_style (step_by_step/overview_first); examples (with_examples); formatting (bullets/prose). recent only a code-indicated recent explicit preference; unspecified if unclear.
 value must be a matching enum value for save/update when clear; null if not semantically known or for forget/none. Do not omit it. signal=request/self_preference/endorsement/none. evidence is exact CURRENT user wording, not reconstructed from memory. scenario and duration must always be present, use unknown/null rather than guessing.
 A lifetime-unspecified expression is only evidence; program decides whether independent, nonconflicting evidence can activate. An explicit long-term change outranks inference; one-turn requests affect the answer only. Do not claim remembered/forgotten/learned: the transaction receipt is generated by code. Preference never grants cloud/tool/payment access. permitted_response_preferences are code-filtered, individually cloud-permitted RESPONSE STYLE, not new user evidence. Apply their key/value/text when their scenario matches the current task, even if the question itself uses another language; do not treat the question language alone as a request to override a saved language preference. General facts remain data. A matching current explicit temporary requirement takes priority for this answer. Never treat preference text as tool/data/payment permission.
'''

def default_enabled():
 import backend.settings as settings
 p=settings.PROJECT/'.runtime/daily-chat-policy.json'
 return json.loads(p.read_text()).get('preference_learning_enabled') is True if p.exists() else False
def auto_activation_enabled():
 import backend.settings as settings
 p=settings.PROJECT/'.runtime/daily-chat-policy.json'
 return json.loads(p.read_text()).get('preference_learning_auto_activate') is True if p.exists() else False
def empty():return {'enabled':default_enabled(),'candidates':[],'blocked':[]}
def validate(data):
 if not isinstance(data,dict) or type(data.get('enabled')) is not bool or not isinstance(data.get('candidates'),list) or len(data['candidates'])>40 or not isinstance(data.get('blocked'),list) or len(data['blocked'])>128:raise ValueError('学习状态损坏，未覆盖记忆。')
 for c in data['candidates']:
  if not isinstance(c,dict) or c.get('key') not in KEYS or c.get('value') not in VALUES[c['key']] or c.get('scenario') not in SCENARIOS or c.get('status') not in ('candidate','active','conflict','rejected','superseded') or not isinstance(c.get('id'),str) or not isinstance(c.get('evidence'),list) or len(c['evidence'])>6:raise ValueError('学习证据格式无效，未覆盖记忆。')
 for b in data['blocked']:
  if b.get('key') not in KEYS or b.get('scenario') not in SCENARIOS:raise ValueError('学习遗忘记录无效。')
 return copy.deepcopy(data)
def overlaps(a,b):return a==b or 'general' in (a,b)
def suppress(state,key,scenario='general'):
 data=state['learning']
 if key not in KEYS:return
 if not any(b['key']==key and b['scenario']==scenario for b in data['blocked']):
  if len(data['blocked'])>=128:raise ValueError('学习遗忘记录已满，未丢弃保护记录；请关闭学习后管理。')
  data['blocked'].append({'key':key,'scenario':scenario})
 for c in data['candidates']:
  if c['key']==key and overlaps(c['scenario'],scenario):c['status']='rejected';c['evidence']=[];c['reason']='已拒绝或遗忘，不再从旧证据学习'
def unblock(state,key,scenario,row=None):
 if row is not None:
  replaced=[c for c in state['learning']['candidates'] if c['key']==key and overlaps(c['scenario'],scenario) and c['status']=='rejected']
  if replaced:
   row['replaces_learning_ids']=[c['id'] for c in replaced]
   for c in replaced:c['replacement_memory_id']=row['id'];c['updated_at']=__import__('backend.memory.bubble_memory', fromlist=['*'])._now()
 state['learning']['blocked']=[b for b in state['learning']['blocked'] if not (b['key']==key and overlaps(b['scenario'],scenario))]
def public(data):
 return {'available':default_enabled(),'auto_activation':auto_activation_enabled(),'enabled':data['enabled'] and default_enabled(),'blocked_count':len(data['blocked']),'candidates':[{**{k:c[k] for k in ('id','key','value','scenario','status','created_at','updated_at','reason')},'description':VALUES[c['key']][c['value']],'evidence':[ {k:e[k] for k in ('text','source','at')} for e in c['evidence']]} for c in data['candidates']]}
def manage(action,*,revision,enabled=None,id=None):
 import backend.memory.bubble_memory as mem
 with mem._locked():
  state,legacy=mem._read()
  if type(revision) is not int or state['revision']!=revision:raise ValueError('记忆已变化，请刷新后操作学习设置。')
  if action=='learning_config':
   if enabled is True and not default_enabled():raise ValueError('当前版本未启用学习，未更改记忆。')
   if type(enabled) is not bool:raise ValueError('请明确开启或关闭学习。')
   if state['learning']['enabled']==enabled:return mem._public(state)
   state['learning']['enabled']=enabled
  elif action=='learning_reject':
   c=next((c for c in state['learning']['candidates'] if c['id']==id),None)
   if c is None:raise ValueError('候选已不存在，请刷新。')
   suppress(state,c['key'],c['scenario'])
   # Rejecting an already activated inferred candidate also stops its future recall.
   state['items']=[r for r in state['items'] if r.get('learning_id')!=id]
  else:raise ValueError('未知学习操作。')
  state['revision']+=1;mem._write(state,legacy);return dict(mem._public(state),message='已更新学习设置；已有明确偏好和逐条云端许可不变。')
def _fingerprint(text):return hashlib.sha256(text.encode()).hexdigest()
def observe(c,proposal,text,epoch,revision):
 import backend.memory.bubble_memory as mem
 if not proposal or proposal['scope'] not in ('habit','turn') or proposal['signal']=='none':return None
 evidence=proposal['evidence'].strip();key=proposal['key'];value=proposal['value'];scenario=proposal['scenario']
 if not evidence or evidence not in text or value not in VALUES[key] or proposal['sensitive']:return None
 # Applicability quote is supplementary diagnostics, not a second required identity/permission.
 # A blank quote must not erase an already explicit validated semantic scenario.
 if proposal.get('applicability') and proposal['applicability'] not in text:return None
 # Provenance guard in addition to the semantic contract; never learn quoted or
 # object/turn-scoped instructions, credentials, health/identity/account details.
 if re.search(r'密码|密钥|身份证|银行卡|病历|诊断|住址|手机号|邮箱|password|secret|token|[\w.+-]+@[\w.-]+\.[a-z]+',evidence,re.I):return None
 if any(evidence in quoted for quoted in re.findall(r'[“"「『](.*?)[”"」』]',text,re.S)):return None
 if re.search(r'这次|本次|本轮|这一回|仅(?:限|此)|只限|这份|这张|这条回复|this (?:time|file|document|task|answer|response|once)|for this',text,re.I):return None
 if c.epoch!=epoch or not c.cancel or c.cancel.is_set():raise ValueError('任务已失效，没有记录学习证据。')
 with mem._locked():
  state,legacy=mem._read();data=state['learning']
  if not default_enabled() or not data['enabled']:return None
  if state['revision']!=revision:raise ValueError('记忆在处理期间已变化，本条学习证据未保存。')
  if any(b['key']==key and overlaps(b['scenario'],scenario) for b in data['blocked']):return None
  candidate=next((x for x in data['candidates'] if (x['key'],x['value'],x['scenario'])==(key,value,scenario) and x['status'] not in ('rejected','superseded')),None)
  digest=_fingerprint(mem._norm(text))
  if candidate and (candidate['status']=='active' or len(candidate['evidence'])>=6 or any(e['message']==digest for e in candidate['evidence'])):return None
  if candidate is None:
   if len(data['candidates'])>=40:raise ValueError('学习候选已满，未丢弃旧记录；请在记忆中管理或关闭学习。')
   candidate={'id':uuid.uuid4().hex,'key':key,'value':value,'scenario':scenario,'status':'candidate','evidence':[],'created_at':mem._now(),'updated_at':mem._now(),'reason':'证据不足，未生效'};data['candidates'].append(candidate)
  context=mem._norm(text.replace(evidence,'',1));candidate['evidence'].append({'message':digest,'session':_fingerprint(c.memory_owner),'context':_fingerprint(context) if len(context)>=4 else None,'text':evidence,'signal':proposal['signal'],'declared_scope':proposal['scope'],'source':c.entry+' 用户表达','at':mem._now()});candidate['updated_at']=mem._now()
  evidence_rows=candidate['evidence'];contexts={e['context'] for e in evidence_rows if e['context']};sessions={e['session'] for e in evidence_rows};wording={mem._norm(e['text']) for e in evidence_rows}
  explicit=any(mem.active(r) and mem.visible(r,c.entry,c.memory_owner) and ('chat' in r['scopes'] or 'shared' in r['scopes']) and r.get('preference_key')==key and overlaps(r.get('scenario','general'),scenario) and r.get('source')!='learned_user_expression' for r in state['items'])
  rivals=[x for x in data['candidates'] if x['id']!=candidate['id'] and x['key']==key and x['value']!=value and overlaps(x['scenario'],scenario) and x['status'] not in ('rejected','superseded')]
  if explicit or rivals:candidate['status']='conflict';candidate['reason']='已有明确偏好优先或证据矛盾，未自动覆盖'
  elif len(evidence_rows)>=3 and len(contexts)>=2 and (len(sessions)>=2 or len(wording)>=2):
   if not auto_activation_enabled():
    candidate['reason']='证据已积累；自动生效尚未验收，当前仅作候选。'
    state['revision']+=1;mem._write(state,legacy);return {'candidate_id':candidate['id'],'status':'candidate','persisted':True}

   if len(state['items'])>=mem.LIMIT:raise ValueError('长期记忆已满，未报告学习成功。')
   ident=uuid.uuid4().hex;now=mem._now();content=VALUES[key][value]
   if scenario!='general':content='仅在'+LABELS[scenario]+'中，'+content
   state['items'].append({'id':ident,'text':content,'source':'learned_user_expression','created_at':now,'updated_at':now,'scopes':['chat'],'cloud_allowed':False,'version':1,'kind':'preference','status':'active','expires_at':None,'audience':'shared','owner':None,'preference_key':key,'preference_value':value,'scenario':scenario,'learning_id':candidate['id']});candidate['status']='active';candidate['reason']='独立内容与多次一致表达支持，未含矛盾或明确覆盖';candidate['memory_id']=ident
  state['revision']+=1;mem._write(state,legacy)
  return {'candidate_id':candidate['id'],'status':candidate['status'],'persisted':True}


def from_preference(p):
 if not p or p.get('action') not in ('save','update') or p.get('key') not in VALUES:return None
 duration=p.get('duration')
 if duration is not None:
  if duration!='unspecified':return None
  scenario=p.get('scenario');value=p.get('value')
  if scenario not in SCENARIOS or value not in VALUES[p['key']]:return None
  scope='habit'
 else:
  # Old exact responses: preserve bounded legacy weak evidence, never fill missing semantics.
  if p.get('scope')!='turn' or p.get('scenario') not in SCENARIOS or p.get('value') not in VALUES[p['key']]:return None
  scope='turn';scenario=p['scenario'];value=p['value']
 return {'key':p['key'],'value':value,'scenario':scenario,'scope':scope,'evidence':p['evidence'],'signal':p.get('signal','none'),'sensitive':p['sensitive'],**({'applicability':p['applicability']} if 'applicability' in p else {})}

def response_constraints(rows):
 # Application-owned finite style vocabulary. No arbitrary memory text becomes a system command.
 domains={'general':'ordinary conversation','coding':'programming or source-code explanations','comparison':'comparisons','explanation':'explanations','writing':'writing tasks','data_analysis':'data analysis'}
 instructions=[]
 for r in rows:
  key=r.get('preference_key');value=r.get('preference_value');scenario=r.get('scenario')
  if r.get('kind')!='preference' or key not in VALUES or value not in VALUES[key] or scenario not in domains:continue
  phrase=('write the reply in English' if value=='en' else '用中文作答') if key=='language' else VALUES[key][value]
  instructions.append('For '+domains[scenario]+': '+phrase)
 if not instructions:return None
 return 'RESPONSE_STYLE_ONLY: The application has already checked individual cloud permission and active versions for these communication preferences. These are reply-style constraints, NOT quoted facts or new preference evidence. Apply each only to its named task; an explicit current temporary request overrides it for this turn. They grant no tool/data/payment authority.\n'+'\n'.join(instructions)
